    #[test]
    fn a_fence_opened_after_a_tab_separated_marker_is_a_fence() {
        assert_eq!(classify("1.\t```sh\n   # x\n   ```\n# Real"), [true, true, true, false]);
    }
}
//! A changeset summary's headline.

use super::fences::{fence_opening, strip_list_marker};
use super::headings::atx_level;

const HEADLINE_MAX_CHARS: usize = 120;

/// A changeset summary split into a one-line headline and the rest.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct SplitSummary {
    /// The first paragraph, on one line. `None` when the summary does not open with a plain paragraph.
    pub(crate) headline: Option<String>,
    /// What the headline does not already say. Empty for a one-paragraph summary.
    pub(crate) detail: String,
}

/// The headline is the summary's first paragraph. A summary opening with a heading, list, quote, table, fence, image or
/// HTML has none, and its whole text is the detail. A paragraph past 120 characters is cut for the headline and
/// kept whole in the detail, so nothing the author wrote is lost.
pub(crate) fn split_summary(summary: &str) -> SplitSummary {
    let text = summary.trim();
    let paragraph: Vec<&str> = text.lines().take_while(|line| !line.trim().is_empty()).collect();
    let opens_a_block = paragraph.first().is_none_or(|line| opens_a_block(line));
    if opens_a_block {
        return SplitSummary {
            headline: None,
            detail: text.to_owned(),
        };
    }
    let headline = paragraph.iter().map(|line| line.trim()).collect::<Vec<_>>().join(" ");
    if headline.chars().count() > HEADLINE_MAX_CHARS {
        let cut: String = headline.chars().take(HEADLINE_MAX_CHARS - 1).collect();
        return SplitSummary {
            headline: Some(format!("{}…", cut.trim_end())),
            detail: text.to_owned(),
        };
    }
    let rest = text
        .lines()
        .skip(paragraph.len())
        .collect::<Vec<_>>()
        .join("\n")
        .trim()
        .to_owned();
    SplitSummary {
        headline: Some(headline),
        detail: rest,
    }
}

/// Whether `line` opens something other than a plain paragraph. It asks the same questions the other passes do, so a
/// heading, list item or fence means here what it means there.
fn opens_a_block(line: &str) -> bool {
    let line = line.trim_start();
    atx_level(line).is_some()
        || strip_list_marker(line) != line
        || fence_opening(line).is_some()
        || ["---", "***", "___"].iter().any(|rule| line.starts_with(rule))
        || line.starts_with(['>', '|', '<'])
        || line.starts_with("![")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_one_paragraph_summary_is_all_headline() {
        let split = split_summary("Uploads now retry.\n");
        assert_eq!(split.headline.as_deref(), Some("Uploads now retry."));
        assert_eq!(split.detail, "");
    }

    #[test]
    fn later_paragraphs_become_the_detail() {
        let split = split_summary("Uploads now retry\nwith backoff.\n\n## Migration\n\nSet `retries = 3`.");
        assert_eq!(split.headline.as_deref(), Some("Uploads now retry with backoff."));
        assert_eq!(split.detail, "## Migration\n\nSet `retries = 3`.");
    }

    #[test]
    fn a_long_headline_is_cut_and_the_detail_keeps_the_whole_text() {
        let long = "word ".repeat(40);
        let split = split_summary(&long);
        let headline = split.headline.unwrap();
        assert!(headline.ends_with('…') && headline.chars().count() <= HEADLINE_MAX_CHARS);
        assert_eq!(split.detail, long.trim());
    }

    #[test]
    fn a_summary_opening_with_a_block_has_no_headline() {
        for opening in [
            "## Migration\n\nText.",
            "- one\n- two",
            "1. first",
            "> quoted",
            "| a | b |\n| - | - |",
            "```sh\nx\n```",
            "~~~\nx\n~~~",
            "![alt](img.png)",
            "<details>",
            "---",
        ] {
            let split = split_summary(opening);
            assert_eq!(split.headline, None, "{opening}");
            assert_eq!(split.detail, opening.trim());
        }
    }

    #[test]
    fn text_that_only_looks_like_a_block_is_a_headline() {
        for (text, headline) in [
            ("`retries` now back off.", "`retries` now back off."),
            ("#hashtag support lands.", "#hashtag support lands."),
            ("**Breaking:** drops the old API.", "**Breaking:** drops the old API."),
            ("*Faster* uploads.", "*Faster* uploads."),
            ("!important flag added.", "!important flag added."),
            ("~Approximately~ right.", "~Approximately~ right."),
        ] {
            let split = split_summary(text);
            assert_eq!(split.headline.as_deref(), Some(headline), "{text}");
            assert_eq!(split.detail, "");
        }
    }

    #[test]
    fn an_empty_summary_has_no_headline() {
        assert_eq!(
            split_summary("  \n"),
            SplitSummary {
                headline: None,
                detail: String::new()
            }
        );
    }

    #[test]
    fn a_tab_separated_or_bare_list_marker_opens_a_block() {
        for opening in [
            "1.\tStop the service\n2.\tRun the migration",
            "-\tone\n-\ttwo",
            "1.",
            "-",
        ] {
            assert_eq!(split_summary(opening).headline, None, "{opening:?}");
        }
        assert_eq!(
            split_summary("1.5x faster uploads.").headline.as_deref(),
            Some("1.5x faster uploads.")
        );
    }

    /// The classifier this module replaced. The new one may call more lines paragraphs, but only the kinds below.
    fn old_starts_a_block(line: &str) -> bool {
        let digits = line.chars().take_while(char::is_ascii_digit).count();
        let numbered = digits > 0 && matches!(line[digits..].chars().next(), Some('.' | ')'));
        numbered
            || line.starts_with(['#', '>', '|', '!', '<', '`', '~'])
            || ["- ", "* ", "+ ", "---", "***"]
                .iter()
                .any(|marker| line.starts_with(marker))
    }

    /// What the new classifier deliberately reads as a paragraph where the old one read a block.
    fn deliberately_a_paragraph(line: &str) -> bool {
        let digits = line.chars().take_while(char::is_ascii_digit).count();
        let numbered_text = digits > 0
            && matches!(line[digits..].chars().next(), Some('.' | ')'))
            && !line[digits + 1..].is_empty()
            && !line[digits + 1..].starts_with([' ', '\t']);
        numbered_text || line.starts_with(['#', '!', '`', '~'])
    }

    proptest::proptest! {
        #[test]
        fn the_new_classifier_only_frees_text_the_old_one_wrongly_blocked(
            marker in proptest::sample::select(vec!["-", "*", "+", "#", "##", ">", "|", "!", "<", "`", "``", "```", "~", "---", "1.", "12)", "1.5", ""]),
            separator in proptest::sample::select(vec!["", " ", "\t", "  ", "x"]),
            tail in "[a-z`# ]{0,4}",
        ) {
            let line = format!("{marker}{separator}{tail}");
            if old_starts_a_block(&line) && !opens_a_block(&line) {
                proptest::prop_assert!(deliberately_a_paragraph(&line), "{line:?} lost its block status");
            }
        }
    }
}
//! Every Markdown pass over the same documents. A pass that disagrees with the others about what is code or what is a
//! heading fails here, so a new pass joins the table instead of growing its own scanner.

use callisto_model::Version;

use super::fences::Fences;
use super::headings::{heading_levels, rebase_headings};
use crate::changelog::write::{find_section, has_heading};

struct Case {
    name: &'static str,
    text: &'static str,
    /// Zero-based lines that are fenced code, fence lines included.
    code: &'static [usize],
    /// `(line, level)` of each heading outside code.
    headings: &'static [(usize, usize)],
}

const CASES: &[Case] = &[
    Case {
        name: "plain",
        text: "Intro line.\n\n## One\n\ntext\n\n### Two\n",
        code: &[],
        headings: &[(2, 2), (6, 3)],
    },
    Case {
        name: "backtick fence",
        text: "## A\n```sh\n# c\n## d\n```\n## B",
        code: &[1, 2, 3, 4],
        headings: &[(0, 2), (5, 2)],
    },
    Case {
        name: "tilde fence",
        text: "~~~\n# t\n~~~\n## B",
        code: &[0, 1, 2],
        headings: &[(3, 2)],
    },
    Case {
        name: "longer closing fence",
        text: "````\n```\n# in\n````\n## After",
        code: &[0, 1, 2, 3],
        headings: &[(4, 2)],
    },
    Case {
        name: "fence opened on a bullet and closed indented",
        text: "- ```md\n  # Title\n  ```\n## After",
        code: &[0, 1, 2],
        headings: &[(3, 2)],
    },
    Case {
        name: "fence opened on a numbered item",
        text: "1. ```sh\n   ## x\n   ```\n## After",
        code: &[0, 1, 2],
        headings: &[(3, 2)],
    },
    Case {
        name: "inline triple backticks are not a fence",
        text: "```a``` text\n## Real",
        code: &[],
        headings: &[(1, 2)],
    },
    Case {
        name: "indented code is not a heading",
        text: "    ## not\n## Real",
        code: &[],
        headings: &[(1, 2)],
    },
    Case {
        name: "a hashtag is not a heading",
        text: "#hashtag\n## Real",
        code: &[],
        headings: &[(1, 2)],
    },
    Case {
        name: "a title ending in a hash",
        text: "### C#\n## Real",
        code: &[],
        headings: &[(0, 3), (1, 2)],
    },
    Case {
        name: "an unclosed fence runs to the end",
        text: "## A\n```\n## never closed\n",
        code: &[1, 2],
        headings: &[(0, 2)],
    },
    Case {
        name: "CRLF line endings",
        text: "```\r\n# x\r\n```\r\n## Real",
        code: &[0, 1, 2],
        headings: &[(3, 2)],
    },
];

#[test]
fn the_fence_tracker_marks_the_expected_lines() {
    for case in CASES {
        let mut fences = Fences::default();
        let code: Vec<usize> = case
            .text
            .lines()
            .enumerate()
            .filter_map(|(index, line)| fences.is_code(line).then_some(index))
            .collect();
        assert_eq!(code, case.code, "{}", case.name);
    }
}

#[test]
fn the_heading_pass_finds_the_expected_headings_and_none_in_code() {
    for case in CASES {
        let lines: Vec<&str> = case.text.split_inclusive('\n').collect();
        let found: Vec<(usize, usize)> = heading_levels(&lines)
            .into_iter()
            .enumerate()
            .filter_map(|(index, level)| level.map(|level| (index, level)))
            .collect();
        assert_eq!(found, case.headings, "{}", case.name);
        assert!(
            found.iter().all(|(index, _)| !case.code.contains(index)),
            "{}: a heading inside code",
            case.name
        );
    }
}

#[test]
fn the_duplicate_heading_check_sees_only_headings_outside_code() {
    for case in CASES {
        for (index, line) in case
            .text
            .lines()
            .enumerate()
            .filter(|(_, line)| line.starts_with("## "))
        {
            let outside_code = !case.code.contains(&index);
            assert_eq!(has_heading(case.text, line), outside_code, "{}: {line:?}", case.name);
        }
    }
}

#[test]
fn a_section_ends_at_the_first_top_level_heading_outside_code() {
    let version = Version::semver(1, 0, 0);
    for case in CASES {
        let document = format!("## 1.0.0\n\n{}\n## 0.9.0\n\nolder entry\n", case.text);
        let end = case
            .headings
            .iter()
            .find(|(_, level)| *level <= 2)
            .map_or(case.text.lines().count(), |(index, _)| *index);
        let expected: String = case.text.lines().take(end).collect::<Vec<_>>().join("\n");

        let found = find_section(&document, &version).map(|section| section.replace("\r\n", "\n"));
        assert_eq!(found.as_deref(), Some(expected.trim()), "{}", case.name);
    }
}

#[test]
fn rebasing_changes_only_heading_lines_and_is_idempotent() {
    for case in CASES {
        let rebased = rebase_headings(case.text, 4);
        assert_eq!(rebase_headings(&rebased, 4), rebased, "{}: not idempotent", case.name);
        for (index, (before, after)) in case.text.lines().zip(rebased.lines()).enumerate() {
            let is_heading = case.headings.iter().any(|(line, _)| *line == index);
            if !is_heading {
                assert_eq!(before, after, "{}: line {index} changed", case.name);
            }
        }
    }
}
//! Heading levels for Markdown an author wrote without knowing where it would land.

use super::fences::Fences;

/// Shifts the headings in `text` so its shallowest one sits at `first_level`, keeping their relative depth. Only the
/// `#` run changes; every other byte passes through. Fenced code and indented code are left alone. A heading pushed
/// past level 6 becomes a bold line, so no text is lost.
pub fn rebase_headings(text: &str, first_level: usize) -> String {
    let lines: Vec<&str> = text.split_inclusive('\n').collect();
    let headings = heading_levels(&lines);
    let Some(shallowest) = headings.iter().flatten().copied().min() else {
        return text.to_owned();
    };

    let mut out = String::with_capacity(text.len());
    for (line, level) in lines.iter().zip(&headings) {
        let Some(level) = level else {
            out.push_str(line);
            continue;
        };
        let target = level + first_level - shallowest;
        out.push_str(&retarget(line, *level, target));
    }
    out
}

/// The ATX heading level of each line, `None` for a line that is not a heading or sits inside a fence.
pub(super) fn heading_levels(lines: &[&str]) -> Vec<Option<usize>> {
    let mut fences = Fences::default();
    lines
        .iter()
        .map(|line| {
            let body = line.trim_end_matches(['\n', '\r']);
            if fences.is_code(body) {
                return None;
            }
            atx_level(body)
        })
        .collect()
}

/// The level of `line` as an ATX heading: one to six `#` after at most three spaces, then a space, a tab or the end of
/// the line. `#hashtag` is text.
pub(super) fn atx_level(line: &str) -> Option<usize> {
    let indent = line.len() - line.trim_start_matches(' ').len();
    if indent >= 4 {
        return None;
    }
    let trimmed = &line[indent..];
    let hashes = trimmed.chars().take_while(|c| *c == '#').count();
    let after = &trimmed[hashes..];
    ((1..=6).contains(&hashes) && (after.is_empty() || after.starts_with([' ', '\t']))).then_some(hashes)
}

fn retarget(line: &str, level: usize, target: usize) -> String {
    let body = line.trim_end_matches(['\n', '\r']);
    let ending = &line[body.len()..];
    let indent = body.len() - body.trim_start_matches(' ').len();
    let after = &body[indent + level..];
    if target <= 6 {
        return format!("{}{}{after}{ending}", &body[..indent], "#".repeat(target));
    }
    let title = without_closing_hashes(after.trim());
    if title.is_empty() {
        return ending.to_owned();
    }
    format!("{}**{title}**{ending}", &body[..indent])
}

/// `title` without an ATX closing sequence: trailing `#`s that follow a space. `C#` keeps its hash.
fn without_closing_hashes(title: &str) -> &str {
    let stripped = title.trim_end_matches('#');
    if stripped.len() == title.len() {
        return title;
    }
    if stripped.is_empty() || stripped.ends_with([' ', '\t']) {
        stripped.trim_end()
    } else {
        title
    }

